num1 = float(input('请输入第一个数: '))
operator = input('请输入运算符(+, -, *, /): ')
num2 = float(input('请输入第二个数: '))

if operator == '+':
    result = num1 + num2
elif operator == '-':
    result = num1 - num2
elif operator == '*':
    result = num1 * num2
elif operator == '/':
    result = num1 / num2 if num2 != 0 else '错误:除数不能为零'
else:
    result = '未知运算符'

print(f'{num1} {operator} {num2} = {result}')

score = int(input('请输入分数(0-100): '))

if score >= 90:
    grade = 'A'
elif score >= 80:
    grade = 'B'
elif score >= 70:
    grade = 'C'
elif score >= 60:
    grade = 'D'
else:
    grade = 'F'

passed = score >= 60
print(f'分数: {score}, 等级: {grade}, 及格: {passed}')
